import subprocess

def run_cmd(cmd):
    try:
        res = subprocess.run(cmd, shell=True, capture_output=True, text=True)
        return res.stdout, res.stderr
    except Exception as e:
        return "", str(e)

print("node:", run_cmd("node -v"))
print("npm:", run_cmd("npm -v"))
print("chromium:", run_cmd("which chromium || which chromium-browser || which google-chrome"))

