# Let's inspect what typesetter.js needs to run in Node.js
# We can create a lightweight DOM mock in Node.js that implements document.getElementById, createElement, appendChild, querySelector, etc.
# and check if performTypeset runs.

mock_script = """
const fs = require('fs');

// Minimal DOM mock
class DOMNode {
    constructor(tagName = 'div') {
        this.tagName = tagName.toUpperCase();
        this.children = [];
        this.style = {};
        this.attributes = {};
        this.className = '';
        this.id = '';
        this.innerHTML = '';
        this.textContent = '';
        this.scrollHeight = 0;
        this.offsetHeight = 0;
        this.clientHeight = 0;
        this.offsetWidth = 272;
    }
    appendChild(child) {
        this.children.push(child);
        child.parentElement = this;
        return child;
    }
    removeChild(child) {
        const idx = this.children.indexOf(child);
        if (idx !== -1) this.children.splice(idx, 1);
        child.parentElement = null;
        return child;
    }
    insertBefore(newChild, refChild) {
        const idx = this.children.indexOf(refChild);
        if (idx !== -1) this.children.splice(idx, 0, newChild);
        else this.children.push(newChild);
        newChild.parentElement = this;
        return newChild;
    }
    getAttribute(name) { return this.attributes[name] || null; }
    setAttribute(name, val) { this.attributes[name] = String(val); }
    hasAttribute(name) { return name in this.attributes; }
    removeAttribute(name) { delete this.attributes[name]; }
    querySelector(sel) {
        return this.querySelectorAll(sel)[0] || null;
    }
    querySelectorAll(sel) {
        const res = [];
        const match = (node) => {
            if (sel.startsWith('.') && node.className.includes(sel.slice(1))) res.push(node);
            else if (sel.startsWith('#') && node.id === sel.slice(1)) res.push(node);
            else if (sel.toUpperCase() === node.tagName) res.push(node);
            for (const c of node.children) match(c);
        };
        for (const c of this.children) match(c);
        return res;
    }
    get lastElementChild() { return this.children[this.children.length - 1] || null; }
    get firstElementChild() { return this.children[0] || null; }
}

global.document = {
    createElement(tag) { return new DOMNode(tag); },
    getElementById(id) { return elements[id] || (elements[id] = new DOMNode('div')); },
    documentElement: new DOMNode('html'),
    body: new DOMNode('body')
};
global.window = {
    getComputedStyle(el) { return el.style || {}; },
    location: {},
    __pageDebugStore: {}
};
global.NodeFilter = { SHOW_TEXT: 4 };

console.log("Mock DOM ready!");
"""

with open("test_mock.js", "w") as f:
    f.write(mock_script)

res = run_cmd("node test_mock.js")
print(res)

